package com.zidee.ress.engine.video

import com.zidee.ress.domain.model.MediaType
import com.zidee.ress.domain.model.PixelSize
import com.zidee.ress.domain.model.StagedOutput
import com.zidee.ress.domain.model.VideoEncodingSpec
import java.io.File

/**
 * Handles output target patterns and collects ordered segment files generated by
 * FFmpeg's `-f segment` muxer.
 */
object StorySegmentSplitter {
    private const val SINGLE_FILENAME = "output.mp4"
    private const val SEGMENT_PATTERN = "part_%02d.mp4"

    fun outputTargetFile(
        jobDir: File,
        spec: VideoEncodingSpec,
    ): File =
        if (spec.segmentSeconds != null) {
            File(jobDir, SEGMENT_PATTERN)
        } else {
            File(jobDir, SINGLE_FILENAME)
        }

    fun collectOutputs(
        jobDir: File,
        outputSize: PixelSize,
        spec: VideoEncodingSpec,
    ): List<StagedOutput> {
        val files =
            if (spec.segmentSeconds != null) {
                jobDir.listFiles { file ->
                    file.isFile && file.name.startsWith("part_") && file.extension.equals("mp4", ignoreCase = true)
                }?.sortedBy { it.name }.orEmpty()
            } else {
                listOf(File(jobDir, SINGLE_FILENAME)).filter { it.isFile }
            }.filter { it.length() > 0L }

        check(files.isNotEmpty()) { "FFmpeg produced no output files in ${jobDir.name}" }

        val totalParts = files.size
        return files.mapIndexed { index, file ->
            val partDuration =
                spec.segmentDurationsMs.getOrNull(index)
                    ?: if (totalParts == 1) spec.segmentDurationsMs.firstOrNull() else null
            StagedOutput(
                cachePath = file.absolutePath,
                mediaType = MediaType.VIDEO,
                size = outputSize,
                sizeBytes = file.length(),
                durationMs = partDuration,
                partIndex = index + 1,
                totalParts = totalParts,
            )
        }
    }
}
